import{_ as s,o as a,a as o,b as e}from"./app.C41L12d5.js";const r="/ascendc.github.io/assets/scenario1_layout_transform.DyRSU9It.png",n="/ascendc.github.io/assets/scenario2_layout_transform.DMeolnuK.png",i="/ascendc.github.io/assets/scenario3_layout_transform.DZBR8UZ3.png",p="/ascendc.github.io/assets/scenario4_layout_transform.C6SlwhCL.png",l="/ascendc.github.io/assets/scenario5_layout_transform.CyNv-i_c.png",c="/ascendc.github.io/assets/scenario6_layout_transform.EJaJUTVP.png",N="/ascendc.github.io/assets/scenario7_layout_transform.BXRYXf78.png",_="/ascendc.github.io/assets/scenario13_3d_tensor_transform.nX2qXOmB.png",d="/ascendc.github.io/assets/scenario14_3d_tensor_transform.sJmyGjZo.png",h="/ascendc.github.io/assets/scenario15_3d_tensor_transform.BA1NHX8N.png",g="/ascendc.github.io/assets/scenario16_nd2nz_interleave_2.C7mVsDxm.png",T="/ascendc.github.io/assets/scenario1_nz2nd_axis12_swap.qpCHeldD.png",m="/ascendc.github.io/assets/scenario2_nz2nz_axis12_swap.CI2VRTrx.png",u="/ascendc.github.io/assets/scenario3_nz2nz_tail_split.Dv_oSMCo.png",S="/ascendc.github.io/assets/scenario4_nz2nd_tail_split.D9mXfD7S.png",D="/ascendc.github.io/assets/scenario5_nz2nd_tail_merge.eShaa3O0.png",H="/ascendc.github.io/assets/scenario6_nz2nz_tail_merge.TrnAGw9X.png",f="/ascendc.github.io/assets/scenario7_2d_transpose.HKQQVCfR.png",v="/ascendc.github.io/assets/scenario13_2d_3d_transpose.CIdAQuOx.png",b="/ascendc.github.io/assets/scenario16_nd2nz_interleave.tbvmlXrn.png",E=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"张量变换","link":"/api/SIMD-API/adv_api/tensor_transform/tensor_transform"},{"text":"Transpose","link":"/api/SIMD-API/adv_api/tensor_transform/Transpose"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/tensor_transform/Transpose.md","filePath":"api/SIMD-API/adv_api/tensor_transform/Transpose.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"实现原理","slug":"实现原理","link":"#实现原理"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787132628000}'),Z={name:"api/SIMD-API/adv_api/tensor_transform/Transpose.md"};function A(B,t,q,C,P,I){return a(),o("div",null,[...t[0]||(t[0]=[e('<div><article class="markdown-body"><h1>Transpose</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>对输入数据进行数据排布及Reshape操作，具体功能如下：</p><p>【场景1：NZ2ND，1、2轴互换】</p><p>输入Tensor { shape:[B, N, H/N/16, S/16, 16, 16], origin_shape:[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, S, N, H/N], origin_shape:[B, S, N, H/N], format:&quot;ND&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图1</strong> 场景1数据排布变换<br><img src="'+r+'" alt title="场景1数据排布变换"></p><p>【场景2：NZ2NZ，1、2轴互换】</p><p>输入Tensor { shape:[B, N, H/N/16, S/16, 16, 16], origin_shape:[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, S, H/N/16, N/16, 16, 16], origin_shape:[B, S, N, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图2</strong> 场景2数据排布变换<br><img src="'+n+'" alt title="场景2数据排布变换"></p><p>【场景3：NZ2NZ，尾轴切分】</p><p>输入Tensor { shape:[B, H / 16, S / 16, 16, 16], origin_shape:[B, S, H], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, N, H/N/16, S / 16, 16, 16], origin_shape:[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图3</strong> 场景3数据排布变换<br><img src="'+i+'" alt title="场景3数据排布变换"></p><p>【场景4：NZ2ND，尾轴切分】</p><p>输入Tensor { shape:[B, H / 16, S / 16, 16, 16], origin_shape:[B, S, H], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, N, S, H/N], origin_shape:[B, N, S, H/N], format:&quot;ND&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图4</strong> 场景4数据排布变换<br><img src="'+p+'" alt title="场景4数据排布变换"></p><p>【场景5：NZ2ND，尾轴合并】</p><p>输入Tensor { shape:[B, N, H/N/16, S/16, 16, 16], origin_shape:[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, S, H], origin_shape:[B, S, H], format:&quot;ND&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图5</strong> 场景5数据排布变换<br><img src="'+l+'" alt title="场景5数据排布变换"></p><p>【场景6：NZ2NZ，尾轴合并】</p><p>输入Tensor { shape:[B, N, H/N/16, S/16, 16, 16], origin_shape:[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, H/16, S/16, 16, 16], origin_shape:[B, S, H], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p><strong>图6</strong> 场景6数据排布变换<br><img src="'+c+'" alt title="场景6数据排布变换"></p><p>【场景7：二维转置】</p><p>支持在Unified Buffer（UB）上对二维Tensor进行转置，其中srcShape中的H、W均是16的整倍。</p><p><strong>图7</strong> 场景7数据排布变换<br><img src="'+N+'" alt title="场景7数据排布变换"></p><p>【场景13：二维转置或者三维的后两维转置】</p><p>支持在UB上对二维Tensor进行转置或者对三维Tensor的最后两维进行转置，二维Tensor转置同场景7的数据排布变换。</p><p><strong>图8</strong> 场景13三维Tensor数据排布变换<br><img src="'+_+'" alt title="场景13三维Tensor数据排布变换"></p><p>【场景14：三维中的第一维和第二维互换】</p><p>支持在UB上对三维Tensor中的第一维和第二维互换。</p><p><strong>图9</strong> 场景14三维Tensor的数据排布变换<br><img src="'+d+'" alt title="场景14三维Tensor的数据排布变换"></p><p>【场景15：三维中的第一维和第三维互换】</p><p>支持在UB上对三维Tensor中的第一维和第三维互换。</p><p><strong>图10</strong> 场景15三维Tensor的数据排布变换<br><img src="'+h+'" alt title="场景15三维Tensor的数据排布变换"></p><p>【场景16：使用交织指令进行两维ND2NZ转置】</p><p>支持在UB上使用<a href="../../basic_api/memory_vector_compute/data_rearrange_ISASI/Interleave.html">交织指令</a>对二维ND Tensor转置为NZ。</p><p><strong>图11</strong> 场景16使用交织指令的ND2NZ转置<br><img src="'+g+'" alt title="场景16使用交织指令的ND2NZ转置"></p><h2 id="实现原理">实现原理<a class="header-anchor" href="#实现原理">​</a></h2><p>对应Transpose的11种功能场景，每种功能场景的算法框图如图所示。</p><p><strong>图12</strong> 场景1：NZ2ND，1、2轴互换<br><img src="'+T+'" alt title="场景1-NZ2ND-1-2轴互换"></p><p>计算过程分为如下几步：</p><p>先后沿H/N方向，N方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：沿S方向转置S/16个连续的16*16的方形到temp中，在temp中每个方形与方形之间连续存储；</li><li>第2次TransDataTo5HD步骤：将temp中S/16个16*16的方形转置到dst中，在dst中是ND格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移(H/N)*N个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移16个元素。</li></ol><p><strong>图13</strong> 场景2：NZ2NZ，1、2轴互换<br><img src="'+m+'" alt title="场景2-NZ2NZ-1-2轴互换"></p><p>计算过程分为如下几步：</p><p>先后沿H/N方向，N方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：沿S方向分别取S/16个连续的16*16的方形到temp中，在temp中每个方形与方形之间连续存储；</li><li>第2次TransDataTo5HD步骤：将temp中S/16个16*16的方形转置到dst中，在dst中是NZ格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移(H/N)*N个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移N*16个元素。</li></ol><p><strong>图14</strong> 场景3：NZ2NZ，尾轴切分<br><img src="'+u+'" alt title="场景3-NZ2NZ-尾轴切分"></p><p>计算过程分为如下几步：</p><p>先后沿H方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：每次转置S/16个连续的16*16的方形到temp1中；</li><li>DataCopy步骤：当H/N&lt;=16时，每次搬运H/N*S个元素到temp2中；当H/N&gt;16时，前H/N/16次搬运16*S个元素到temp2中，最后一次搬运H/N%16*S个元素到temp2中；</li><li>第2次TransDataTo5HD步骤：将temp2中的16*S的方形转置到dst中，在dst中是NZ格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移16个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移S*16个元素。</li></ol><p><strong>图15</strong> 场景4：NZ2ND，尾轴切分<br><img src="'+S+'" alt title="场景4-NZ2ND-尾轴切分"></p><p>计算过程分为如下几步：</p><p>先后沿H方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：每次转置S/16个连续的16*16的方形到temp1中；</li><li>DataCopy步骤：当H/N&lt;=16时，每次搬运H/N*S个元素到temp2中；当H/N&gt;16时，前H/N/16次搬运16*S个元素到temp2中，最后一次搬运H/N%16*S个元素到tmp2中；</li><li>第2次TransDataTo5HD步骤：将temp2中的数据转置到dst中，在dst中是ND格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移(H/N+16-1)/16*16个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移(H/N+16-1)/16*16*S个元素。</li></ol><p><strong>图16</strong> 场景5：NZ2ND，尾轴合并<br><img src="'+D+'" alt title="场景5-NZ2ND-尾轴合并"></p><p>计算过程分为如下几步：</p><p>先后沿H方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：每次转置一个S*16的方形到temp1中；</li><li>DataCopy步骤：当H/N&lt;=16时，每次搬运H/N*S个元素到temp2中；当H/N&gt;16时，前H/N/16次搬运16*S个元素到temp2中，最后一次搬运H/N%16*S个元素到tmp2中；</li><li>第2次TransDataTo5HD步骤：将temp2中的16*S的方形转置到dst中，在dst中是ND格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移(H+16-1)/16*16个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移H/N*S个元素。</li></ol><p><strong>图17</strong> 场景6：NZ2NZ，尾轴合并<br><img src="'+H+'" alt title="场景6-NZ2NZ-尾轴合并"></p><p>计算过程分为如下几步：</p><p>先后沿H方向，B方向循环处理：</p><ol><li>第1次TransDataTo5HD步骤：每次转置一个S*16的方形到temp1中；</li><li>DataCopy步骤：当H/N&lt;=16时，每次搬运H/N*S个元素到temp2中；当H/N&gt;16时，前H/N/16次搬运16*S个元素到temp2中，最后一次搬运H/N%16*S个元素到tmp2中；</li><li>第2次TransDataTo5HD步骤：将temp2中的16*S的方形转置到dst中，在dst中是NZ格式，来自同一个方形的连续2行数据在目的操作数上的地址偏移16个元素，沿H方向的每2个方形的同一行数据在目的操作数上的地址偏移S*16个元素。</li></ol><p><strong>图18</strong> 场景7：二维转置<br><img src="'+f+'" alt title="场景7-二维转置"></p><p>计算过程如下：</p><ol><li>调用TransDataTo5HD，通过设置不同的源操作数地址序列和目的操作数地址序列，将[H, W]转置为[W, H]，src和dst均是ND格式。</li></ol><p><strong>图19</strong> 场景13 : 二维转置或者三维的后两维转置<br><img src="'+v+'" alt title="场景13-二维转置或者三维的后两维转置"></p><p>计算过程如下：</p><ol><li>调用内部计算逻辑，通过设置不同的源操作数地址序列，连续写入目的操作数地址中，将[H, W]转置为[W, H]，或者将[N, H, W]转置为[N, W, H]，src和dst均是ND格式。</li></ol><p>场景14、场景15的转换过程和上述场景13中三维转置的转换过程基本一致，只是指定转置的维度不同。</p><p><strong>图20</strong> 场景16 ：使用交织指令进行两维ND2NZ转置<br><img src="'+b+`" alt title="场景16-使用交织指令进行两维ND2NZ转置"></p><p>计算过程如下：</p><ol><li>调用内部计算逻辑，通过设置不同的源操作数地址序列，连续写入目的操作数地址中，将[H, W] ND格式转置为[W1,H1,H0,W0] NZ格式，H = H1 * H0，W = W1 * W0，H0=16，W0=2，src是ND格式，dst是NZ格式。</li></ol><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><p>由于该接口的内部实现中涉及复杂的计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间大小BufferSize的获取方法：通过<a href="Transpose-Tiling.html">Transpose Tiling</a>中提供的<strong>GetTransposeMaxMinTmpSize</strong>接口获取所需最大和最小临时空间大小，最小空间可以保证功能正确，最大空间用于提升性能。</p><p>临时空间支持<strong>接口框架申请</strong>和开发者<strong>通过sharedTmpBuffer入参传入</strong>两种方式，因此Transpose接口的函数原型有两种：</p><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;typename T&gt;
__aicore__ inline void Transpose(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, TransposeType transposeType, ConfusionTransposeTiling&amp; tiling)
</code></pre></div><p>该方式下开发者需自行申请并管理临时内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li><li><p>接口框架申请临时空间</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;typename T&gt;
__aicore__ inline void Transpose(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, TransposeType transposeType, ConfusionTransposeTiling&amp; tiling)
</code></pre></div><p>该方式下开发者无需申请，但是需要预留临时空间的大小。</p></li></ul><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。<br><br>场景1到场景7支持的数据类型为：int16_t、uint16_t、half、int32_t、uint32_t、float；场景13到场景15支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float；场景16支持的数据类型为：int8_t、uint8_t。</td></tr></tbody></table><p><strong>表2</strong> 接口参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，LocalTensor数据结构的定义请参考<a href="../../basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>。<br><br>类型为<a href="../../basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，LocalTensor数据结构的定义请参考<a href="../../basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>。<br><br>类型为<a href="../../basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>共享缓冲区，用于存放API内部计算产生的临时数据。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。共享缓冲区大小的获取方式请参考<a href="Transpose-Tiling.html">Transpose Tiling</a>。<br><br>类型为<a href="../../basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>transposeType</td><td>输入</td><td>数据排布及reshape的类型，类型为TransposeType枚举类，TransposeType的定义如下方代码所示。</td></tr><tr><td>tiling</td><td>输入</td><td>计算所需tiling信息，Tiling信息的获取请参考<a href="Transpose-Tiling.html">Transpose Tiling</a>。</td></tr></tbody></table><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>enum class TransposeType : uint8_t {
    TRANSPOSE_TYPE_NONE,           // default value
    TRANSPOSE_NZ2ND_0213,          // 场景1：NZ2ND，1、2轴互换
    TRANSPOSE_NZ2NZ_0213,          // 场景2：NZ2NZ，1、2轴互换
    TRANSPOSE_NZ2NZ_012_WITH_N,    // 场景3：NZ2NZ，尾轴切分
    TRANSPOSE_NZ2ND_012_WITH_N,    // 场景4：NZ2ND，尾轴切分
    TRANSPOSE_NZ2ND_012_WITHOUT_N, // 场景5：NZ2ND，尾轴合并
    TRANSPOSE_NZ2NZ_012_WITHOUT_N, // 场景6：NZ2NZ，尾轴合并
    TRANSPOSE_ND2ND_ONLY,          // 场景7：二维转置
    TRANSPOSE_ND_UB_GM,            // 当前不支持
    TRANSPOSE_GRAD_ND_UB_GM,       // 当前不支持
    TRANSPOSE_ND2ND_B16,           // 当前不支持
    TRANSPOSE_NCHW2NHWC,           // 当前不支持
    TRANSPOSE_NHWC2NCHW,           // 当前不支持
    TRANSPOSE_ND2ND_021,           // 场景13：二维转置或者三维中后两维转置
    TRANSPOSE_ND2ND_102,           // 场景14：三维中第一维和第二维互换
    TRANSPOSE_ND2ND_210,           // 场景15：三维中第一维和第三维互换
    TRANSPOSE_ND2NZ_WITH_INTLV     // 场景16：使用交织指令进行两维ND2NZ转置
};
</code></pre></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</li></ul><div data-filter="950"><ul><li>场景13到场景16仅在Ascend 950PR/Ascend 950DT上支持。</li><li>Ascend 950PR/Ascend 950DT，场景13到场景16不支持dst和src空间复用。</li></ul></div><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>本示例为场景1（NZ2ND，1、2轴互换）示例：</p><p>输入Tensor { shape:[B, N, H/N/16, S/16, 16, 16], origin_shape：[B, N, S, H/N], format:&quot;NZ&quot;, origin_format:&quot;ND&quot;}</p><p>输出Tensor { shape:[B, S, N, H/N], origin_shape:[B, S, N, H/N], format:&quot;ND&quot;, origin_format:&quot;ND&quot;}</p><p>B=1，N=2, S=64, H/N=32，输入数据类型均为half。更多完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/08_transpose/transpose">Transpose样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// dst：输出Tensor
// src：输入Tensor
// NZ2ND，1、2轴互换
AscendC::Transpose(dst, src, AscendC::TransposeType::TRANSPOSE_NZ2ND_0213, this-&gt;tiling);
</code></pre></div></article></div>`,1)])])}const O=s(Z,[["render",A]]);export{E as __pageData,O as default};
